pub fn roll(&mut self, pins: u16) -> Result<(), Error> {
    if self.done {
        return Err(Error::GameComplete);
    }
    if self.frame < 10 {
        let allowed = if self.rolls_in_frame == 0 { 10 } else { 10 - self.frame_pins };
        if pins > allowed {
            return Err(Error::NotEnoughPinsLeft);
        }
        self.rolls.push(pins);
        self.frame_pins += pins;
        self.rolls_in_frame += 1;
        if self.rolls_in_frame == 2 || self.frame_pins == 10 {
            self.frame += 1;
            self.rolls_in_frame = 0;
            self.frame_pins = 0;
            if self.frame == 10 {
                // just finished frame 9 (0-indexed)
                let last_frame = &self.rolls[self.rolls.len() - 2..];
                let was_strike = last_frame.len() == 1 && last_frame[0] == 10;
                self.bonus = if was_strike { 2 } else if last_frame.iter().sum::<u16>() == 10 { 1 } else { 0 };
                if self.bonus == 0 { self.done = true; }
            }
        }
    } else {
        // frame 10 bonus balls
        let allowed = if self.bonus == 2 { 10 } else {
            // bonus == 1: depends on whether the 2nd roll in frame 10 was a strike
            let second = self.rolls[self.rolls.len() - 1];
            if second == 10 { 10 } else { 10 - second }
        };
        if pins > allowed {
            return Err(Error::NotEnoughPinsLeft);
        }
        self.rolls.push(pins);
        self.bonus -= 1;
        if self.bonus == 0 {
            self.done = true;
        }
    }
    Ok(())
}
```

