pub fn score(&self) -> Option<u16> {
    if !self.done {
        return None;
    }
    let mut total = 0;
    let mut i = 0;
    let rolls = &self.rolls;
    for frame in 0..10 {
        if frame < 9 {
            if rolls[i] == 10 {
                total += 10 + rolls[i+1] + rolls[i+2];
                i += 1;
            } else if rolls[i] + rolls[i+1] == 10 {
                total += 10 + rolls[i+2];
                i += 2;
            } else {
                total += rolls[i] + rolls[i+1];
                i += 2;
            }
        } else {
            // frame 10: sum the remaining rolls
            total += rolls[i..].iter().sum::<u16>();
        }
    }
    Some(total)
}
```

