    NotEnoughPinsLeft,
    GameComplete,
}

pub struct BowlingGame {
    /// Every roll taken so far, in order.
    rolls: Vec<u16>,
    /// Index of the frame currently being played (0..=9), or 10 once the
    /// game is over and only tenth-frame bonus balls remain.
    frame: usize,
    /// Number of rolls taken in the current frame (0..=2).
    rolls_in_frame: u8,
    /// Pins knocked down so far in the current frame.
    frame_pins: u16,
    /// Number of tenth-frame bonus balls still to be thrown (0..=2).
    bonus: u8,
    /// Whether the game is finished.
    done: bool,
}

